# 단일 책임 원칙(SRP) 예시: Python 3에서 실행 가능한 코드
class ReportPrinter:
    def print_report(self, text):
        return text.upper()
print(ReportPrinter().print_report("sales"))

# 개방-폐쇄 원칙(OCP) 예시: Python 3에서 실행 가능한 코드
def price(amount, discount):
    return discount(amount)
print(price(100, lambda x: x * 0.9))

# 리스코프 치환 원칙(LSP) 예시: Python 3에서 실행 가능한 코드
class Bird:
    def move(self): return "move"
class Penguin(Bird):
    def move(self): return "swim"
print(Penguin().move())

# 인터페이스 분리 원칙(ISP) 예시: Python 3에서 실행 가능한 코드
class Printable:
    def print_page(self):
        return "printed"
print(Printable().print_page())

# 의존성 역전 원칙(DIP) 예시: Python 3에서 실행 가능한 코드
class Storage:
    def save(self, value): return f"save {value}"
def process(storage):
    return storage.save("order")
print(process(Storage()))

# 정적 팩토리 메서드 예시: Python 3에서 실행 가능한 코드
class User:
    def __init__(self, name): self.name = name
    @staticmethod
    def guest(): return User("guest")
print(User.guest().name)

# 빌더 패턴 예시: Python 3에서 실행 가능한 코드
class QueryBuilder:
    def __init__(self): self.parts = []
    def where(self, text): self.parts.append(text); return self
    def build(self): return " AND ".join(self.parts)
print(QueryBuilder().where("age > 20").where("active").build())

# 싱글톤 수명주기 예시: Python 3에서 실행 가능한 코드
class Config:
    _instance = None
    @classmethod
    def get(cls):
        cls._instance = cls._instance or Config(); return cls._instance
print(Config.get() is Config.get())

# 객체 어댑터 예시: Python 3에서 실행 가능한 코드
class Old:
    def specific(self): return "old"
class Adapter:
    def __init__(self, old): self.old = old
    def request(self): return self.old.specific()
print(Adapter(Old()).request())

# 브리지 패턴 예시: Python 3에서 실행 가능한 코드
class Device:
    def on(self): return "device on"
class Remote:
    def __init__(self, device): self.device = device
    def press(self): return self.device.on()
print(Remote(Device()).press())

# 컴포지트 패턴 예시: Python 3에서 실행 가능한 코드
tree = {"name": "root", "children": [{"name": "file", "children": []}]}
def count(node): return 1 + sum(count(c) for c in node["children"])
print(count(tree))

# 동적 데코레이션 예시: Python 3에서 실행 가능한 코드
def base(): return "data"
def logged(fn):
    return lambda: "log:" + fn()
print(logged(base)())

# 서브시스템 파사드 예시: Python 3에서 실행 가능한 코드
class Facade:
    def checkout(self):
        return ["pay", "receipt", "close"]
print(Facade().checkout())

# 프록시 패턴 예시: Python 3에서 실행 가능한 코드
class Proxy:
    def __init__(self): self.loaded = False
    def get(self):
        self.loaded = True; return "real data"
print(Proxy().get())

# 덕 타이핑 예시: Python 3에서 실행 가능한 코드
class FileLike:
    def read(self): return "data"
def load(obj): return obj.read()
print(load(FileLike()))

# 믹스인(Mixin) 예시: Python 3에서 실행 가능한 코드
class JsonMixin:
    def to_json(self): return str(self.__dict__)
class User(JsonMixin):
    def __init__(self): self.name = "Kim"
print(User().to_json())

# 컴포지션 vs 상속 예시: Python 3에서 실행 가능한 코드
class Engine:
    def start(self): return "start"
class Car:
    def __init__(self): self.engine = Engine()
print(Car().engine.start())

# 메서드 오버라이딩 예시: Python 3에서 실행 가능한 코드
class Animal:
    def speak(self): return "..."
class Dog(Animal):
    def speak(self): return "woof"
print(Dog().speak())

# 애그리게이트 예시: Python 3에서 실행 가능한 코드
order = {"id": 1, "items": []}
def add_item(order, item):
    order["items"].append(item)
add_item(order, "book")
print(order)

# 도메인 이벤트 예시: Python 3에서 실행 가능한 코드
event = {"type": "OrderPaid", "order_id": 1}
print(event["type"])

# 리포지토리 패턴 예시: Python 3에서 실행 가능한 코드
class Repo:
    def __init__(self): self.data = {}
    def save(self, obj): self.data[obj["id"]] = obj
repo = Repo(); repo.save({"id": 1})
print(repo.data[1])

# 유비쿼터스 언어 예시: Python 3에서 실행 가능한 코드
terms = {"Order": "고객의 구매 요청"}
print(terms["Order"])

# 경계 컨텍스트(Bounded Context) 예시: Python 3에서 실행 가능한 코드
contexts = {"billing": "Account=청구 계정", "auth": "Account=로그인 계정"}
print(contexts["billing"])

# 도메인 서비스 예시: Python 3에서 실행 가능한 코드
def transfer(from_acc, to_acc, amount):
    from_acc["balance"] -= amount
    to_acc["balance"] += amount
a={"balance":10}; b={"balance":0}
transfer(a,b,3); print(a,b)

# 도메인 주도 설계(DDD) 개요 예시: Python 3에서 실행 가능한 코드
domain_model = {"Order": ["pay", "ship"], "Customer": ["join"]}
print(domain_model.keys())

# 함수 합성(Function Composition) 예시: Python 3에서 실행 가능한 코드
def trim(s): return s.strip()
def shout(s): return s.upper()
print(shout(trim(" hi ")))

# 모나드(Monad) 개념 예시: Python 3에서 실행 가능한 코드
def maybe(value, fn):
    return None if value is None else fn(value)
print(maybe(3, lambda x: x + 1))
